// ===== Jarvis settings: edit these two lines, then click Publish =====

const BOT_TOKEN = 'PASTE_YOUR_BOT_TOKEN_HERE';  // from @BotFather: /mybots → your bot → API Token
const OWNER_ID  = 0;                            // your Telegram user ID (a number). Leave 0 at first:
                                                // send /start to your bot and Jarvis tells you your ID.

// ===== nothing to change below =====
if (!/^\d{5,}:[A-Za-z0-9_-]{30,}$/.test(BOT_TOKEN)) {
  throw new Error('Settings: paste your bot token into BOT_TOKEN (it looks like 123456789:AAF...)');
}
return [{ json: { bot_token: BOT_TOKEN, owner_id: Number(OWNER_ID) || 0 } }];

// Telegram's answer: { ok, result: [ update, update, ... ] }
const updates = $input.first().json.result || [];
if (updates.length === 0) return [];   // nothing new: stop here

const OWNER_ID = $('Settings').first().json.owner_id;
const lastId = Math.max(...updates.map(u => u.update_id));
const mine = updates
  .map(u => u.message)
  .filter(m => m && m.from && !m.from.is_bot && m.chat && m.chat.type === 'private')
  .filter(m => OWNER_ID === 0 || m.from.id === OWNER_ID);   // 0 = setup mode: Jarvis only tells you your ID

// One item: the offset that confirms these updates, plus my messages
return [{ json: { offset: lastId + 1, messages: mine } }];

const messages = $('Keep only my messages').first().json.messages;
const OWNER_ID = $('Settings').first().json.owner_id;
const memory = $getWorkflowStaticData('global');   // survives between runs of this published workflow
memory.chats = memory.chats || {};

const out = [];
for (const m of messages) {
  const chat_id = m.chat.id;
  const key = String(chat_id);
  const name = m.from.first_name || 'friend';
  const text = (m.text || '').trim();

  if (OWNER_ID === 0) {
    out.push({ json: { chat_id, skip_ai: true, reply:
      `Setup: your Telegram user ID is ${m.from.id}.\n\nIn n8n, open the Settings node, set OWNER_ID = ${m.from.id}, then click Publish. After that, only you can talk to me.` } });
    continue;
  }
  if (!m.text) {
    const reply = m.voice
      ? 'I got your voice note. I can only read text for now; I learn to listen in Lesson 10.'
      : 'I can only read text messages for now.';
    out.push({ json: { chat_id, reply, skip_ai: true } });
    continue;
  }
  if (text === '/start' || text === '/new') {
    memory.chats[key] = [];
    const reply = text === '/start'
      ? `Hi ${name}, I'm Jarvis. Write to me any time. Send /new to start a fresh conversation.`
      : 'OK, fresh start. I forgot our earlier conversation.';
    out.push({ json: { chat_id, reply, skip_ai: true } });
    continue;
  }

  const system = `You are Jarvis, the personal assistant of ${name}. ` +
    'Reply in the same language the user writes in (Urdu in Urdu script, English, Arabic...). ' +
    'Be warm, clear and brief: this is a Telegram chat on a phone. Plain text, short paragraphs, no tables. ' +
    'You cannot take actions yet (no calendar, reminders or PC control): if asked, say honestly that this skill is coming.';
  const history = memory.chats[key] || [];
  out.push({ json: {
    chat_id, text, skip_ai: false,
    body: { model: 'smart', messages: [ { role: 'system', content: system }, ...history, { role: 'user', content: text } ] }
  } });
}
return out;

const asked = $('Prepare each message').item.json;   // the message this answer belongs to
const r = $input.item.json;
let reply = r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content;
reply = (reply || '').trim();
if (!reply) reply = "Sorry, my brain didn't answer just now. Please try again in a minute.";

// Keep the last 10 exchanges (20 messages) per chat
const memory = $getWorkflowStaticData('global');
memory.chats = memory.chats || {};
const key = String(asked.chat_id);
memory.chats[key] = (memory.chats[key] || [])
  .concat([ { role: 'user', content: asked.text }, { role: 'assistant', content: reply } ])
  .slice(-20);

return { json: { chat_id: asked.chat_id, reply } };
